INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 1, 'Aconteceu que, depois da morte de Moisés, servo do Senhor, o Senhor falou a Josué, filho de Nun, ministro de Moisés, e disse-lhe:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 2, 'Meu servo Moisés morreu; levanta-te e passa esse Jordão, tu e todo o povo contigo, entra na terra que eu darei aos filhos de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 3, 'Todo o lugar, que pisar a planta do vosso pé, eu vo-lo darei, como disse a Moisés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 4, 'Desde o deserto e desde o Líbano até ao grande rio Eufrates — todo o país dos Heteus — e até ao mar grande para o ocidente, todo este território será vosso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 5, 'Ninguém vos poderá resistir em todos os dias da vossa vida; como fui com Moisés, assim serei contigo; não te deixarei, nem desampararei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 6, 'Tem ânimo e sê forte, porque tu hás-de levar este povo à posse da terra, que prometi com juramento a seus pais que lhes havia de dar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 7, 'Tem ânimo pois, reveste-te de grande fortaleza, para cuidadosamente cumprir toda a lei, que Moisés, meu servo, te prescreveu; não te desvies dela nem para a direita nem para a esquerda, a fim de que sejas feliz em tudo o que fizeres.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 8, 'Não se aparte da tua boca o livro desta lei, mas medita nele dia e noite, cuidando de cumprir tudo o que nele está escrito; então prosperarás em teus caminhos e serás bem sucedido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 9, 'Porventura não te ordenei: tem ânimo, e sê forte? — Não tenhas, pois, medo nem temor, porque o Senhor teu Deus está contigo em qualquer parte para onde vás.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 10, 'Deu Josué aos príncipes do povo esta ordem: Percorrei os acampamentos, e mandai ao povo o seguinte:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 11, 'Fazei provisão de mantimentos, porque daqui a três dias haveis de passar o Jordão, e entrareis a possuir a terra, que o Senhor vosso Deus vos dá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 12, 'Disse também aos Rubenitas, aos Gaditas e à meia tribo de Manassés:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 13, 'Lembrai-vos do que vos ordenou Moisés, servo do Senhor, quando vos disse: O Senhor vosso Deus vos deu descanso, e toda esta terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 14, 'Vossas mulheres, filhos e animais, ficarão na terra, que Moisés vos deu àquem do Jordão, mas vós todos os que sois (mais) valentes passai armados à frente de vossos irmãos, e pelejai por eles'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 15, 'até que o Senhor dê descanso a vossos irmãos, como o deu a vós, e também eles possuam a terra, que o Senhor vosso Deus lhes dá; depois voltareis para a terra que possuís, (para a terra ) que Moisés, servo do Senhor, vos deu àquem do Jordão, para o nascente, e habitareis nela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 16, 'Eles, respondendo a Josué, disseram: Nós faremos tudo o que nos ordenaste; iremos para onde quer que nos mandares.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 17, 'Assim como em tudo obedecemos a Moisés, assim obedeceremos também a ti; sòmente (desejamos) que o Senhor teu Deus seja contigo, como foi com Moisés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 18, 'Aquele que contradisser as tuas palavras, que não obedecer a tudo o que lhe mandares, seja morto. Tu (da tua parte) tem ânimo, opera varonilmente (que nós te seguiremos).');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 1, 'Josué, filho de Nun, enviou secretamente de Setim dois espiões, e disse-lhes: Ide, examinai o país e a cidade de Jericó. Eles partiram e entraram em casa duma meretriz, chamada Raab, e repousaram em sua casa. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 2, 'E foi dado aviso disso ao rei de Jericó, assim: entraram aqui de noite uns homens dos filhos de Israel, para explorar o país.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 3, 'O rei de Jericó mandou dizer a Raab; Faze sair esses homens, que foram ter contigo e entraram em tua casa, porque são espiões que vieram reconhecer todo o país.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 4, 'Mas a mulher, tomando os homens, escondeu-os, e disse: Confesso que eles vieram a minha casa, mas eu não sabia donde eram,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 5, 'e, quando se fechava a porta (da cidade), sendo já escuro, eles saíram ao mesmo tempo, e não sei para onde foram. Ide após eles, depressa, e encontrá-los-eis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 6, 'Ora ela tinha feito subir os homens ao terraço da sua casa e tinha-os coberto com palha de linho, que ali havia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 7, 'Os que haviam sido enviados, foram atrás deles pelo caminho que conduz ao vau do Jordão, e, logo que saíram, foi fechada a porta (da cidade).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 8, 'Ainda os homens, que estavam escondidos, não tinham adormecido, quando a mulher subiu junto deles e lhes disse:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 9, 'Eu sei que o Senhor vos entregou este país; o terror de vós apoderou-se de nós, e todos os habitantes do pais desanimaram,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 10, 'pois soubemos que o Senhor secou as águas do Mar Vermelho à vossa entrada, quando saistes do Egipto, e (soubemos) o que fizestes aos dois reis dos Amorreus, que estavam da banda de além do Jordão, Seon e Og, os quais matastes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 11, 'Quando ouvimos isto, tivemos grande medo, o nosso coração desmaiou e não ficou alento em nós à vossa aproximação; porque o Senhor vosso Deus é o (mesmo) Deus (que reina ) lá em cima no céu, e cá em baixo na terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 12, 'Agora pois jurai-me pelo Senhor, que, assim como eu usei de misericórdia convosco, assim usareis com a casa de meu pai, e dai-me um sinal seguro'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 13, 'de que salvareis meu pai e minha mãe, meus irmãos e minhas irmãs, assim como tudo o que lhes pertence, e livrareis as nossas vidas da morte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 14, 'Eles responderam-lhe: À custa da nossa vida salvaremos a vossa, contanto que tu nos não atraiçoes; quando o Senhor nos entregar este país, usaremos contigo de misericórdia e de fidelidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 15, 'Ela os fez descer da janela por uma corda, porque a sua casa estava pegada ao muro (da cidade).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 16, 'Disse-lhes: Ide para o monte, não suceda que eles vos encontrem, quando voltarem, e deixai-vos lá estar escondidos durante três dias, até que eles voltem, e depois tomareis o vosso caminho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 17, 'Eles disseram-lhes: Nós cumpriremos fielmente o juramento, que nos fizeste prestar,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 18, 'se, quando entrarmos no país, estiver como sinal este cordão cor de escarlate, e o atares à janela, por onde nos fizeste descer, e se tiveres recolhido, em tua casa, o teu pai, a tua mãe, os teus irmãos e toda a tua parentela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 19, 'Se alguém sair da porta da tua casa, o seu sangue cairá sobre a sua cabeça, e nós ficaremos sem culpa; mas o sangue de todos os que estiverem contigo em tua casa cairá sobre a nossa cabeça, se alguém os tocar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 20, 'Porém, se tu nos atraiçoares, e publicares isto que te dizemos, ficaremos desobrigados deste juramento, que nos fizeste prestar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 21, 'Ela respondeu: Faça-se como dissestes. Depois os despediu e eles partiram; (então) pendurou o cordão cor de escarlate à janela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 22, 'Eles, andando, chegaram ao monte, e lá permaneceram durante três dias, até que voltaram os que tinham ido em seu seguimento. Estes, tendo buscado por todo o caminho (os espiões), não os encontraram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 23, '(Então) os espiões deram volta, e, tendo descido do monte e passado o Jordão, chegaram a Josué, filho de Nun, e contaram-lhe tudo o que lhes tinha acontecido,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 24, 'dizendo: O Senhor entregou todo este país nas nossas mãos, pois os seus habitantes estão consternados de medo.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 1, 'Josué Ievantando-se de madrugada, moveu o acampamento e saiu de Setim. Chegados ao Jordão, ele e todos os filhos de Israel, aí se detiveram, antes de o atravessar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 2, 'Passados três dias, os pregoeiros atravessaram pelo meio do acampamento,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 3, 'e começaram a dizer em alta voz: Logo que virdes a arca da aliança do Senhor vosso Deus levada pelos sacerdotes da linhagem de Levi, levantai-vos vós, também, e ide atrás dela,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 4, 'mas de forma que haja entre vós e a arca o espaço de dois mil côvados, a fim de a poderdes ver de longe, e conhecer o caminho por onde deveis ir, porque não andastes antes por ele; tomai cuidado, não vos aproximeis da arca. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 5, 'Josué disse ao povo: Santificai-vos, porque amanhã o Senhor fará entre vós maravilhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 6, 'Depois Josué falou aos sacerdotes: Tomai a arca da aliança e ide adiante do povo. Eles, executando a sua ordem, tomaram (a arca), e caminharam adiante do povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 7, 'O Senhor disse a Josué: Hoje começarei a exaltar-te diante de todo o Israel, para que saibam que, assim como fui com Moisés, assim sou contigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 8, 'Aos sacerdotes que levam a arca da aliança, dá-lhes esta ordem: Quando tiverdes chegado às águas do Jordão, parai aí.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 9, 'Josué disse aos filhos de Israel: Aproximai-vos, e ouvi a palavra do Senhor vosso Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 10, 'E acrescentou: Por isto conhecereis que o Senhor, o Deus vivo, está no meio de vós, e exterminará à vossa vista o Cananeu, o Heteu, o Heveu, o Fereseu, o Gergeseu, o Jebuseu e o Amorreu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 11, 'Eis que a arca da aliança do Senhor de toda a terra irá adiante de vós pelo meio do Jordão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 12, 'Preparai doze homens das tribos de Israel, um de cada tribo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 13, 'Logo que os sacerdotes, que levam a arca de Javé, o Senhor de toda a terra, puserem as plantas de seus pés nas águas do Jordão, as águas debaixo seguirão a sua corrente e minguarão, e as que vêm de cima, pararão, amontoando-se.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 14, 'Quando saiu o povo das suas tendas, para passar o Jordão, os sacerdotes, que levavam a arca da aliança, caminhavam adiante dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 15, 'No momento em que entraram no Jordão, e a água lhes começou a molhar os pés (porque o Jordão, sendo o tempo da ceifa, inundava as margens do seu leito),'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 16, 'as águas, que vinham de cima, pararam num só lugar, e, levantando-se à maneira dum monte, descobriam-se de longe desde a cidade, que se chama Adom, até ao lugar de Sartan; e as que desciam continuaram a correr para o mar do deserto (que agora se chama Mar Morto), até que faltaram de todo. Entretanto o povo caminhava para Jericó.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 17, 'Os sacerdotes, que levavam a arca da aliança do Senhor, conservavam-se quietos, de pé, sobre a terra seca, no meio do Jordão, e todo o povo ia passando pelo leito do rio, a pé enxuto.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 1, 'Depois que passaram, o Senhor disse a Josué:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 2, 'Escolhe doze homens, um de cada tribo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 3, 'e manda-lhes que tomem do meio do leito do Jordão, onde os pés dos sacerdotes estiveram parados, doze pedras duríssimas, as quais vós colocareis no lugar do acampamento, em que esta noite haveis de plantar as tendas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 4, 'Chamou pois Josué os doze homens, que tinha escolhido entre os filhos de Israel, um de cada tribo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 5, 'e disse-lhes: Ide adiante da arca do Senhor vosso Deus ao meio do Jordão, e trazei de lá cada um a sua pedra sobre os ombros, segundo o número (das tribos) dos filhos de Israel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 6, 'para que seja um sinal entre vós; quando no futuro vossos filhos vos perguntarem: Que significam estas pedras?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 7, '— vós lhes respondereis: As águas do Jordão desapareceram diante de arca da aliança do Senhor, enquanto ela o atravessava; por isso se puseram estas pedras como um memorial eterno dos filhos de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 8, 'Fizeram os filhos de Israel como Josué Ihes tinha ordenado, levando do meio do leito do Jordão, doze pedras, segundo o número (das tribos) dos filhos de Israel, consoante o Senhor tinha mandado a Josué, até no lugar onde acamparam, e ali as puseram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 9, 'Pôs também Josué outras doze pedras no meio do leito do Jordão, onde estiveram parados os sacerdotes, que levavam a arca da aliança, e elas ainda ali se conservam até ao dia de hoje.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 10, 'Os sacerdotes, quo levavam a arca, estavam parados no meio do Jordão, até se cumprir tudo o que o Senhor tinha mandado a Josué que dissesse ao povo, de acordo com o que Moisés havia prescrito. E o povo apressou-se, e passou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 11, 'Logo que passaram todos, passou também a arca do Senhor, e os sacerdotes iam (com ela) adiante do povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 12, 'Os filhos de Ruben e de Gad, e a meia tribo de Manassés, precediam, armados, os filhos de Israel, como Moisés lhes tinha ordenado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 13, 'Quarenta mil combatentes marchavam à frente, divididos em filas e esquadrões pelas planícies e campinas da cidade de Jericó.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 14, 'Naquele dia o Senhor engrandeceu Josué diante de todo o Israel, para eles o reverenciarem, como tinham reverenciado a Moisés, quando vivia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 15, '(O Senhor) disse-lhe:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 16, 'Manda aos sacerdotes, que levam a arca da aliança, que saiam do Jordão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 17, 'Ele ordenou-lhes: Saí do Jordão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 18, 'Quando saíram os que levavam a arca da aliança do Senhor e começaram a pisar a terra seca, tornaram as águas ao seu leito e correram como costumavam antes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 19, 'Ora o povo saiu do Jordão, no dia dez do primeiro mês, e acampou em Galgala, ao oriente da cidade de Jericó.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 20, 'Colocou também Josué em Galgala as doze pedras, que tinham tomado do fundo do Jordão,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 21, 'e disse aos filhos de Israel: Quando no futuro os vossos filhos perguntarem a seus pais: Que significam estas pedras?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 22, '— vós os informareis, dizendo-lhes: Israel passou a pé enxuto este Jordão,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 23, 'tendo o Senhor vosso Deus secado as suas águas à vossa vista, até que passásseis, do mesmo modo que antes tinha feito no Mar Vermelho, o qual secou até que passássemos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 24, 'para que todos os povos da terra reconheçam a mão poderosíssima do Senhor, e vós temais sempre o Senhor vosso Deus.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 1, 'Quando todos os reis dos Amorreus, que habitavam na outra banda do Jordão, ao ocidente, e todos os reis de Canaan, que possuíam os lugares vizinhos do Mar Grande, ouviram dizer que o Senhor tinha secado a corrente do Jordão diante dos filhos de Israel, até que passassem, enfraqueceu-se-lhes o coração, não ficou neles alento, temendo a entrada dos filhos de Israel. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 2, 'Então o Senhor disse a Josué: Faze facas de pedra, e restabelece novamente a circuncisão entre os filhos de Irsrael. Josué, fazendo o que o Senhor lhe mandara, circuncidou os filhos de Israel sobre o outeiro (chamado por isso) da Circuncisão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 3, 'A causa desta circuncisão é a seguinte: Todos os varões dentre o povo, que tinham saído do Egipto, todos os homens de guerra tinham morrido no deserto durante os larguíssimos rodeios do caminho,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 5, 'e todos estes tinham sido circuncidados. Porém o povo que nasceu no deserto,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 6, 'durante os quarenta anos de marcha por aquela vastíssima solidão, permaneceu incircunciso, até que morreram aqueles que não tinham obedecido à voz do Senhor, e aos quais ele antes tinha jurado que lhes não mostraria a terra que manava leite e mel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 7, 'Os filhos destes foram postos (pelo Senhor) no lugar de seus pais, o circuncidou-os Josué, porque estavam incircuncisos, visto que ninguém os tinha circuncidado no caminho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 8, 'Depois que foram todos circuncidados, permaneceram acampados no mesmo lugar, até sararem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 9, 'O Senhor disse a Josué: Hoje tirei de cima de vós o opróbrio do Egipto. E foi dado àquele lugar o nome de Galgala até ao dia de hoje. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 10, 'Os filhos de Israel permaneceram em Galgala, onde celebraram a Páscoa, no dia catorze do mês, pela tarde, na planície de Jericó;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 11, 'ao outro dia comeram dos frutos da terra, pães ázimos, e trigo tostado naquele mesmo dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 12, 'O maná cessou, depois que comeram dos frutos da terra, e os filhos de Israel não usaram mais deste alimento, mas comeram dos frutos que a terra de Canaan tinha dado naquele ano.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 13, 'Ora, estando Josué nos arredores da cidade de Jericó, levantou os olhos e viu diante de si um homem em pé, que tinha uma espada desembaínhada; foi ter com ele, e disse-lhe: Tu és dos nossos ou dos inimigos?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 14, 'Ele respondeu: Não; sou o príncipe do exército do Senhor, que agora venho (para vos auxiliar).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 15, 'Josué caiu com o rosto por terra, prostrou-se e disse-lhe: Que diz o meu Senhor ao seu servo?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 16, 'Tira, lhe respondeu ele, o calçado de teus pés, porque o lugar, em que estás, é santo. Josué fez como lhe tinha sido mandado.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 1, 'Jericó estava fechada e bem fortificada, pelo temor dos filhos de Israel, e ninguém ousava sair nem entrar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 2, 'O Senhor disse a Josué: Olha que eu pus na tua mão Jericó, o seu rei e todos os seus homens valentes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 3, 'Dai a volta à cidade, vós todos os homens de guerra, uma vez por dia; assim fareis durante seis dias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 4, 'No sétimo dia, os sacerdotes tomem as sete trombetas, de que se usa no jubileu, e vão adiante da arca da aliança; rodeareis sete vezes a cidade, e os sacerdotes tocarão as trombetas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 5, 'Quando o som das trombetas se fizer ouvir mais demorado e penetrante, e vos ferir os ouvidos, todo o povo à uma levantará um grande clamor, e cairão os muros da cidade até aos fundamentos; então cada um entrará por aquele lugar que lhe ficar defronte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 6, 'Chamou pois Josué, filho de Nun, os sacerdotes, e disse-lhes: Tomai a arca da aliança, e outros sete sacerdotes tomem as sete trombetas do jubileu, e vão adiante da arca do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 7, 'Disse também ao povo; Ide e, armados, dai volta à cidade, à frente da arca do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 8, 'Logo que Josué acabou de falar, os sete sacerdotes tocaram as sete trombetas diante da arca da aliança do Senhor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 9, 'e todo o exército armado marchava adiante; o resto da multidão ia atrás da arca, e por toda a parte retinia o som das trombetas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 10, 'Josué havia dado esta ordem ao povo: Não gritareis, nem se ouvirá a vossa voz, nem sairá da vossa boca uma só palavra até que chegue o dia em que eu vos diga: Gritai e levantai a voz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 11, 'Deu pois a arca do Senhor uma volta à cidade, uma vez no (primeiro) dia, e, tornando para o acampamento, ficou ali.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 12, '(No dia seguinte) levantando-se Josué ainda de noite, tomaram os sacerdotes a arca do Senhor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 13, 'e sete deles (tomaram) as sete trombetas, que servem no (ano do) jubileu. Puseram-se em marcha à frente da arca do Senhor, andando e tocando, e o povo armado ia adiante deles, e o resto da multidão seguia a arca, e as trombetas ressoavam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 14, 'Deram volta à cidade uma vez, no segundo dia, e voltaram para o acampamento. Assim fizeram durante seis dias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 15, 'Mas, ao sétimo dia, levantando-se de madrugada, deram volta à cidade sete vezes, como tinha sido ordenado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 16, 'Quando os sacerdotes tocavam as trombetas à sétima volta, Josué disse a todo o Israel: Gritai, porque o Senhor vos entregou a cidade;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 17, 'e esta cidade seja anátema e tudo o que há nela seja do Senhor; fique só com vida a meretriz Baab com todos os que estão em sua casa, porque ocultou os mensageiros que enviámos. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 18, 'Vós, porém, guardai-vos de tocar alguma daquelas coisas que vos foram proibidas, para que vos não torneis réus de prevaricação, e todo o acampamento de Israel não fique sob o pecado, e não seja posto em desordem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 19, 'Tudo o que se encontrar de ouro e prata, de utensílios de cobre e de ferro, seja consagrado ao Senhor e depositado nos seus tesouros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 20, 'Levantando pois todo o povo um grande clamor, ao ouvir o som das trombetas dos sacerdotes, caíram de repente os muros, e cada um subiu pelo lugar que lhe ficava defronte. Tomaram a cidade,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 21, 'mataram tudo o que nela havia, desde os homens até as mulheres, desde as crianças até aos velhos. Passaram também ao fio da espada os bois, as ovelhas e os jumentos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 22, 'Josué disse aos dois homens que tinham sido enviados como espiões: Entrai em casa da mulher meretriz, e fazei-a sair com tudo o que lhe pertence, como vós lho prometestes com juramento.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 23, 'Tendo aqueles jovens entrado, tiraram para fora Raab e seus pais, assim como os irmãos, e tudo o que lhes pertencia, e toda a sua parentela, e fizeram-nos permanecer fora do acampamento de Israel. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 24, 'Puseram fogo à cidade e a tudo o que nela havia, à excepção do ouro e da prata, dos utensílios de cobre e de ferro, que consagraram para o tesouro do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 25, 'Josué salvou a vida a Raab, a meretriz, à casa de seu pai e a todos os seus, que ficaram habitando no meio de Israel até ao dia de hoje, porque ela ocultara os mensageiros, que ele tinha enviado a reconhecer Jericó. Naquele tempo proferiu Josué esta imprecação:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 26, 'Maldito seja diante do Senhor o homem que levantar e reedificar a cidade de Jericó; morra o seu primogénito, quando lhe lançar os fundamentos, e perca o último do seus filhos, quando lhe puser as portas. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 27, 'Foi o Senhor com Josué, e o seu nome divulgou-se por toda a terra.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 1, 'Porém os filhos de Israel violaram o mandamento, a respeito do anátema. Achan, filho de Charmi, filho de Zabdi, filho de Zaré, da tribo de Judá, tomou alguma coisa dada ao anátema, e o Senhor irou-se contra os filhos de Israel. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 2, 'Josué, enviando de Jericó homens contra Hai, que está junto de Betaven, ao nascente da cidade de Betel, disse-lhes: Ide e reconhecei o país. Eles, cumprindo com as ordens, reconheceram Hai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 3, 'A o voltarem disseram-lhe: Não suba todo o povo, mas vão só dois ou três mil homens e destruam a cidade; porque se há-de fatigar inùtilmente todo o povo contra tão poucos inimigos?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 4, 'Subiram pois três mil combatentes, os quais, voltando logo as costas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 5, 'foram batidos pelos homens da cidade de Hai, caindo mortos trinta e seis homens; os inimigos perseguiram-nos, desde a porta (de Hai ) até Sabarim, e mataram-nos enquanto fugiam pela encosta; e o coração do povo desmaiou e perdeu toda a coragem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 6, 'Então Josué rasgou as suas vestes e prostrou-se com o rosto por terra diante da arca do Senhor (e assim esteve) até à tarde, tanto ele como todos os anciãos de Israel, e lançaram cinza sobre as suas cabeças.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 7, 'Josué disse: Ah! Senhor Javé, porque quiseste que este povo passasse o rio Jordão, para nos entregares nas mãos do Amorreu e para nos perderes? Oxalá nós tivéssemos ficado da outra banda do Jordão, como tínhamos começado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 8, 'Que direi eu, Senhor Deus meu, vendo Israel voltar costas aos seus inimigos?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 9, 'Os Cananeus, e todos os habitantes da terra o ouvirão, e, unindo-se todos, nos cercarão, e apagarão o nosso nome da terra; e que farás tu ao teu grande nome?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 10, 'O Senhor disse a Josué: Levanta-te; por que jazes tu prostrado por terra?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 11, 'Israel pecou, a ponto de violar o meu pacto, até tomar das coisas dadas ao anátema, roubá-las, mentir, escondê-las entre as bagagens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 12, 'Israel não pode ter-se diante dos seus inimigos, e foge deles, porque se manchou com o anátema; eu não serei mais convosco, enquanto não exterminardes aquele que é réu desta maldade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 13, 'Levanta-te, santifica o povo e diz-lhes: Santificai-vos para amanhã, porque isto diz o Senhor Deus de Israel: O anátema está no meio de ti, ó Israel; tu não poderás fazer frente aos teus inimigos, até que seja exterminado do meio de ti o que se acha manchado deste crime.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 14, 'Amanhã apresentar-vos-eis (diante do Senhor) cada um nas vossas tribos; a tribo sobre que cair a sorte, se apresentará pelas suas tribos, e caiu a sorte sobre a tribo de Judá, suas casas; a casa (sobre que cair a sorte), pelos seus homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 15, 'O que for tomado como atingido pelo anátema será queimado com todas as suas coisas, porque violou o pacto do Senhor, e cometeu uma coisa detestável em Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 16, 'Josué, levantando-se pela manhã, fez juntar Israel pelas suas famílias; a família (sobre que cair a sorte), pelas'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 17, 'Tendo-se apresentado esta pelas suas famílias, caiu a sorte sobre a família de Zaré. Apresentando-se também esta pelas suas casas, caiu sobre (a casa de) Zabdi;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 18, 'sorteados os indivíduos varões desta casa, um por um, descobriu-se ser Achan, filho de Charmi, filho de Zabdi, filho de Zaré, da tribo de Judá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 19, 'Josué disse a Achan: Ó meu filho, dá glória ao Senhor Deus de Israel, e confessa-me, declara-me o que fizeste, não o ocultes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 20, 'Achan respondeu a Josué: Na verdade eu pequei contra o Senhor Deus de Israel. Eis o que fiz:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 21, 'Vi entre os despojos uma capa de escarlate muito boa, duzentos siclos de prata e uma barra de ouro de cinquenta siclos, e, cobiçando, tirei (estas coisas), escondi-as na terra, no meio da minha tenda, e enterrei o dinheiro numa cova.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 22, 'Mandou pois Josué investigadores, os quais, correndo à tenda de Achan, acharam tudo escondido no mesmo lugar, e debaixo, o dinheiro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 23, 'Tirando-o da tenda, levaram-no a Josué e a todos os filhos de Israel, e lançaram-no fora diante do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 24, 'Então Josué, e todo o Israel com ele, pegando em Achan, filho de Zaré, e na prata e na capa, e na barra de ouro, e em seus filhos e filhas, nos seus bois, jumentos, ovelhas, na própria tenda, e em tudo quanto tinha, levaram-nos ao vale de Achor, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 25, 'onde Josué disse: Pois que tu nos turbaste, o Senhor te conturbe neste dia. E todo o Israel o apedrejou, e tudo o que lhe pertencia foi consumido no fogo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 26, 'E juntaram sobre ele um grande montão de pedras, o qual permanece até ao dia de hoje. (Com isto) apartou-se deles o furor do Senhor. Por isso, até ao dia de hoje, se chama aquele lugar Vale de Achor.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 1, 'O Senhor disse a Josué: Não temas, nem te acobardes; toma contigo todos os combatentes, e, levantando-te, sobe à cidade de Hai; eis que te entreguei nas tuas mãos o seu rei, o povo, a cidade e o seu território.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 2, 'Farás à cidade de Hai e ao seu rei, como fizeste a Jericó e ao seu rei. Todavia repartireis entre vós a presa e todos os animais; põe uma emboscada à cidade por detrás dela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 3, 'Levantou-se Josué com todo o exército dos combatentes, para marchar contra Hai. Mandou de noite trinta mil homens escolhidos dos mais valentes,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 4, 'dando-lhes esta ordem: Armai uma emboscada por detrás da cidade; não vos afasteis muito (dela), e estai todos apercebidos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 5, 'Eu e o resto da gente que está comigo, avançaremos pela parte oposta contra a cidade. Quando eles saírem contra nós, fugiremos e voltar-lhes-emos as costas, como primeiro fizemos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 6, 'até que, perseguindo-nos, se tenham afastado da cidade, pois dirão: fogem de nós como da primeira vez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 7, 'Enquanto formos fugindo, e eles seguindo-nos, vós saireis da emboscada e destruireis a cidade. O Senhor vosso Deus vo-la entregará nas vossas mãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 8, 'Depois que a tiverdes tomado, ponde-lhe fogo e assim fareis tudo como eu mandei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 9, 'Despediu-os, e eles foram para o lugar da emboscada, entro Betei e Hai, ao poente da cidade de Hai. Josué ficou aquela noite no meio do povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 9, 'Despediu-os, e eles foram para o lugar da emboscada, entre Betei e Hai, ao poente da cidade de Hai. Josué ficou aquela noite no meio do povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 10, 'Levantando-se de madrugada, passou revista à sua gente e marchou com os anciãos à frente do exército, sustentado com o grosso das suas tropas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 11, 'Tendo chegado e subido até junto de Hai, fizeram alto no lado setentrional da cidade, entre a qual e eles mediava um vale.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 12, 'Josué tinha escolhido cinco mil homens, e tinha-os posto de emboscada entre Betei e Hai, ao poente da mesma cidade;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 13, 'todo o resto do exército marchava em ordem de batalha para o setentrião, de sorte que os últimos daquela multidão alcançavam até ao poente da cidade. Josué marchou aquela noite e parou no meio do vale.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 14, 'O rei de Hai, tendo visto isto, saiu a toda a pressa da cidade, ao amanhecer, com todo o exército, e encaminhou as suas tropas para a banda do deserto, ignorando que lhe ficava atrás uma emboscada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 15, 'Josué, porém, e todo o Israel foram-se retirando, fingindo medo, e fugindo pelo caminho do deserto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 16, 'Os de Hai, levantando ao mesmo tempo uma grande gritaria e animando-se mutuamente, foram-nos perseguindo. Quando já estavam longe da cidade,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 17, 'sem que tivesse ficado nem sequer um em Hai e em Betei, que não saísse em perseguição de Israel, (deixando abertas as cidades donde tinham saído de tropel),'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 18, 'o Senhor disse o Josué: Levanta o escudo que tens na mão contra a cidade de Hai, porque eu ta entregarei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 19, 'Tendo ele levantado o escudo contra a cidade, imediatamente saíram os que estavam escondidos na emboscada e, encaminhando-se para a cidade, tomaram-na e puzeram-lhe fogo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 20, 'Os homens da cidade, que perseguiam Josué, olhando para trás e vendo o fumo da cidade que subia até ao céu, não puderam já fugir nem para cá nem para lá, principalmente quando os que davam mostra de fugir e corriam para o deserto, atacaram com grande esforço aqueles que os iam perseguindo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 21, 'Josué e todo o Israel, vendo que a cidade estava tomada e que dela subia o fumo, voltaram-se para trás e passaram à espada os de Hai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 22, 'Também os que tinham tomado e queimado a cidade, saindo dela para se unirem com os seus, começaram a bater os inimigos que estavam no meio. Assim, foram os inimigos feridos por uma e outra parte, de modo que nem um se salvou de tão grande multidão;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 23, '(os homens de Israel) tomaram vivo o rei da cidade de Hai e apresentaram-no a Josué.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 24, 'Mortos pois todos aqueles que tinham perseguido Israel fugindo para o deserto, passados completamente todos, no mesmo lugar, ao fio da espada, voltaram os filhos de Israel e destruíram a cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 25, 'Os que morreram naquele dia entre homens e mulheres, foram doze mil, todos da cidade de Hai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 26, 'Josué não retirou a mão, que tinha levantada, segurando o escudo, até que foram mortos todos os habitantes de Hai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 27, 'Os animais e o despojo da cidade, os repartiram entre si os filhos de Israel, como o Senhor tinha ordenado a Josué.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 28, 'Este pôs fogo (ao resto) da cidade, reduzindo-a para sempre a um montão (de ruínas),'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 29, 'e suspendeu de uma árvore o seu rei até à tarde. Ao pôr do sol, mandou que descessem o seu cadáver da árvore e o lançassem na mesma entrada da cidade, pondo sobre ele um grande montão de pedras, que (ali) permanece até ao dia de hoje.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 30, 'Então Josué edificou um altar ao Senhor Deus de Israel sobre o monte Hebal,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 31, 'conforme o que Moisés, servo do Senhor, tinha ordenado aos filhos de Israel, e como está escrito no livro da lei de Moisés, um altar de pedras toscas, nas quais não tocou ferro, e ofereceu sobre ele holocaustos ao Senhor, assim como sacrifícios pacíficos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 32, 'Escreveu sobre pedras o Deuteronómio da lei de Moisés, que ele tinha explicado diante dos filhos de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 33, 'Todo o povo, os anciães, os capitães e os juízes, estavam em pé, a um e outro lado da arca, diante dos sacerdotes que levavam a arca da aliança do Senhor; (ali estavam) tanto os estrangeiros como os naturais, metade junto do monte Garizim, e a outra metade junto do Monte Hebal, como tinha mandado Moisés, servo do Senhor. Primeiramente (Josué) abençoou o povo de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 34, 'Depois disto leu todas as palavras da bênção e da maldição, e tudo o que estava escrito no livro da lei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 35, 'Não omitiu nenhuma das coisas que Moisés tinha ordenado, leu-as todas diante de toda a multidão de Israel, das mulheres, dos meninos e dos estrangeiros, que moravam entre eles.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 1, 'Divulgadas estas coisas, todos os reis da outra banda do Jordão, que moravam nos montes, nas planícies e nos litorais do Mar Grande, e também os que moravam Junto do Líbano, o Heteu, o Amorreu, o Cananeu, o Fereseu, o Heveu e o Jebuseu,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 2, 'uniram-se entre si para combater contra Josué e contra Israel, de comum acordo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 3, 'Porém os habitantes de Gabaon, ouvindo tudo o que Josué tinha feito a Jericó e a Hai,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 4, 'e, usando de astúcia, tomaram consigo víveres, carregaram sobre os seus jumentos arcos velhos, odres de vinho rotos e recosidos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 5, 'levaram calçado muito velho, que, em sinal de muito uso, estava cheio de remendos, e vestiram-se de roupas muito usadas; até os pães, que levavam para o caminho, eram duros e desfeitos em pedaços.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 6, 'Foram ter com Josué, que então se encontrava no acampamento de Galgala, e disseram a ele e a todo o Israel: Nós viemos de uma terra muito distante, com o desejo de fazer pazes convosco. Os homens de Israel responderam-lhes:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 7, 'Não sereis vós talvez moradores na terra, que nos é devida por sorte? como poderemos (em tal caso) fazer aliança convosco?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 8, 'Mas eles disseram a Josué: Nós somos teus servos. Aos quais Josué disse: Quem sois vós? donde viestes?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 9, 'Eles responderam: Os teus servos vieram de uma terra muito distante em nome do Senhor teu Deus, porque ouvimos a fama do seu poder, tudo o que fez no Egipto,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 10, 'e (como tratou) os dois reis dos Amorreus, que estavam da outra banda do Jordão, Seon rei de Hesebon, e Og rei de Basan, que estava em Astarot.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 11, 'Os nossos anciães e todos os habitantes da nossa terra disseram-nos: Tomai provisões para uma tão longa jornada, ide ao seu encontro e dizei-Ihes: Nós somos vossos servos, fazei aliança connosco.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 12, 'Eis os pães, que tomamos quentes quando partimos de nossas casas para vir ter convosco, agora estão secos e desfeitos por demasiadamente antigos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 13, 'Estes odres eram novos, quando os enchemos de vinho, e agora estão rotos e descosidos; a roupa que nos cobre, e o calçado que trazemos nos pés, gastaram-se, quase se consumiram com um tão longo caminho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 14, 'Tomaram pois (os Israelitas) dos viveres deles, e não consultaram o oráculo do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 15, 'Josué fez paz com eles, e, contraindo aliança, prometeu que não seriam mortos, e o mesmo juraram os príncipes do povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 16, 'Porém, três dias depois de ter sido feita aliança, souberam que eles habitavam na vizinhança, e que haviam de viver entre eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 17, 'Então os filhos de Israel moveram o acampamento e, ao terceiro dia, chegaram às suas cidades, cujos nomes são estes; Gabaon, Cafira, Berot e Cariatiarim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 18, 'Não os mataram, por causa do juramento que os príncipes do povo tinham feito, em nome do Senhor Deus de Israel. Pelo que todo o povo murmurou contra os príncipes,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 19, 'os quais responderam: Nós jurámos-lhes, em nome do Senhor Deus de Israel, e por isso não podemos tocar-lhes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 20, 'Todavia tratá-los-emos assim: Fiquem embora salvos com vida, para que não se excite contra nós a ira do Senhor, se faltarmos ao juramento,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 21, 'mas vivam com a obrigação de cortarem lenha e acarretarem água para o serviço de todo o povo. Estando eles a dizer isto,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 22, 'Josué chamou os Gabaonitas e disse-lhes: Porque nos quisestes enganar com (a vossa) fraude, dizendo: Nós habitamos muito longe de vós, sendo que viveis no meio de nós?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 23, 'Por isso estareis debaixo de maldição, e não faltará da vossa linhagem quem corte lenha e acarrete água para a casa do meu Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 24, 'Eles responderam: A nós, teus servos, chegou a noticia de que o Senhor teu Deus tinha prometido a Moisés, seu servo, que vos daria toda a terra e extinguiria todos os seus habitantes. Tivemos, pois, muito medo, e, compelidos pelo terror que vós cansáveis, tomámos este expediente para segurarmos as nossas vidas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 25, 'Agora estamos nas tuas mãos; faz de nós o que te parecer bom e justo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 26, 'Fez pois Josué, como tinha dito, e livrou-os das mãos dos filhos de Israel, para que os não matassem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 27, 'Determinou naquele dia que fossem empregados no serviço de todo o povo e do altar do Senhor, cortando lenha e conduzindo água ao lugar que o Senhor escolhesse, (como o fazem) até ao presente.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 1, 'Adonisedec, rei de Jerusalém, tendo ouvido que Josué tomara Hai e a destruíra (porque fez a Hai e ao seu rei, como tinha feito a Jericó e ao seu rei), e que os Gabaonitas se tinham passado para Israel e se tinham tornado seus aliados,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 2, 'teve muito medo. Com efeito, Gabaon era uma cidade grande, como uma das cidades reais, ainda maior que a cidade de Hai, e todos os seus guerreiros muito valentes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 3, 'Enviou pois Adonisedec, rei de Jerusalém (mensageiros) a Ohan, rei de Hebron, a Faran, rei de Jerimot, a Jafia, rei de Laquis e a Dabir, rei de Eglon, dizendo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 4, 'Vinde ter comigo e trazei-me socorro, a fim de tomarmos Gabaon, porque ela passou para Josué e para os filhos de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 5, 'Unidos pois os cinco reis dos Amorreus, o rei de Jerusalém, o rei de Hebron, o rei de Jerimot, o rei de Laquis, o rei de Eglon, saíram com os seus exércitos, e acamparam junto a Gabaon, sitiando-a.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 6, 'Os habitantes da sitiada cidade de Gabaon mandaram dizer a Josué, que estava então acampado em Galgala: Não recuses a tua mão aos teus servos; vem depressa, livra-nos, dá-nos socorro, porque se coligaram contra nós todos os reis dos Amorreus, que habitam nas montanhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 7, 'Josué subiu de Galgala, e com ele todo o exército dos combatentes, homens valentíssimos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 8, 'O Senhor disse a Josué: Não os temas, porque eu os entreguei nas tuas mãos: nenhum deles te poderá resistir.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 9, 'Josué, tendo marchado toda a noite desde Galgala, deu de repente sobre eles,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 10, 'e o Senhor os desbaratou à vista de Israel; (Israel) infligiu-lhes uma grande derrota, junto de Gabaon, e foi-os perseguindo pelo caminho que sobe a Bet-horon, batendo-os até Azeca e Maceda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 11, 'Enquanto eles fugiam dos filhos de Israel e estavam na descida de Bet-horon, fez o Senhor cair do céu grandes pedras em cima deles até Azeca, e morreram muitos mais pelas pedras do granizo, do que pelos golpes da espada dos filhos de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 12, 'Então Josué falou ao Senhor, no dia em que entregou o Amorreu nas mãos dos filhos de Israel, e disse em presença deles: Sol, não te movas de sobre Gabaon, e tu, lua, (não te movas) de sobre o vale de Ajalon. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 13, 'E o sol e a lua pararam, até que o povo se vingou de seus inimigos. Não está isto escrito no livro do Justo? Parou pois o sol no meio do céu, e não se apressou a pôr-se durante quase o espaço de um dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 14, 'Não houve nem antes nem depois um dia tão longo, obedecendo o Senhor à voz de um homem, porque combatia por Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 15, 'E Josué voltou com todo o Israel para o acampamento de Galgala.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 16, 'Ora os cinco reis tinham fugido, e tinham-se escondido numa caverna da cidade de Maceda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 17, 'E noticiaram a Josué que os cinco reis tinham sido encontrados escondidos numa caverna da cidade de Maceda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 18, 'Ele ordenou aos que o acompanhavam: Rolai pedras grandes para a boca da caverna e ponde homens cuidadosos, que guardem os que nela estão escondidos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 19, 'vós porém não estejais parados, mas persegui os inimigos e matai os fugitivos que forem ficando atrás; não deixeis entrar nas fortalezas das suas cidades aqueles que o Senhor entregou nas vossas mãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 20, 'Tendo sido feito, pois, grande destroço nos inimigos, quase até ao extermínio, aqueles que puderam fugir de Israel, acolheram-se às cidades fortes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 21, 'Todo o exército salvo e em número completo voltou para Josué, a Maceda, onde então estava o acampamento; ninguém (dos adversários) se atreveu a abrir a boca contra os filhos de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 22, 'Josué disse: Abri a boca da caverna e trazei-me os cinco reis, que nela estão escondidos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 23, 'Eles fizeram como Ihes fora mandado, e levaram-Ihe os cinco reis: o rei de Jerusalém, o rei de Hebron, o rei de Jerimot, o rei de Laquis, o rei de Eglon.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 24, 'Quando foram conduzidos perante ele, chamou todos os varões de Israel e disse aos chefes do exército que estavam com ele: Ide e ponde o pé sobre os pescoços destes reis. Tendo eles ido e posto os pés sobre os pescoços dos reis subjugados, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 25, 'disse-lhes de novo: Não temais nem vos acobardeis, tende ânimo, sede fortes, porque assim fará o Senhor a todos os vossos inimigos, contra quem pelejais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 26, 'Depois disto, Josué feriu-os e tirou-lhes a vida, e mandou-os pendurar em cinco forcas, onde estiveram até à tarde.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 27, 'Ao pôr do sol, mandou aos companheiros que os descessem dos patíbulos. Depois de descidos, lançaram-nos nas cavernas, em que se tinham escondido, e puseram à entrada grandes pedras, que ali se conservam até hoje.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 28, 'No mesmo dia Josué tomou também Maceda, e passou-a a fio de espada, matou o seu rei e todos os seus habitantes, sem deixar um só. E fez ao rei de Maceda, como tinha feito ao rei de Jericó.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 29, 'De Maceda passou com todo o Israel a Lebna, combatia contra ela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 30, 'O Senhor entregou-a com o seu rei nas mãos de Israel, que passou a fio de espada a cidade com todos os seres vivos que lá se encontravam, não deixando escapar nenhum. Fizeram ao rei de Lebna como tinham feito ao rei de Jericó.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 31, 'De Lebna passou a Laquis com todo o Israel, e, postado o exército em volta da cidade, atacou-a.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 32, 'O Senhor entregou Laquis nas mãos de Israel, que a tomou no dia seguinte, e a passou ao fio de espada, com todos os seres vivos que estavam dentro, como tinha feito a Lebna.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 33, 'Nesta ocasião Horão, rei de Gazer, subiu em socorro de Laquis, mas Josué derrotou-o com todo o seu povo até ao extermínio completo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 34, 'De Laquis foi a Eglon, sitiou-a,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 35, 'e no mesmo dia a tomou; passou a fio de espada todos os seres vivos, que estavam dentro, conforme tudo o que tinha feito a Laquis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 36, 'Passou, depois, com todo o Israel, de Eglon a Hebron, e combateu contra ela;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 37, 'tomou-a e passou-a também a fio de espada com o seu rei, todos os povos daquela região e todos os seres vivos que nela moravam; não deixou ali ninguém com vida; como tinha feito a Eglon, assim fez a Hebron, passando à espada tudo o que encontrou,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 38, 'Dali voltou-se contra Dabir,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 39, 'tomou-a e destruiu-a; passou também a fio de espada o seu rei e todas as cidades circunvizinhas; não deixou nela resto algum; como tinha feito a Hebron e a Lebna e aos seus reis, assim fez a Dabir e ao seu rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 40, 'Josué destruiu todo o território das montanhas, do meio dia e da planície e Asedot com os seus reis; não deixou ali resto algum, mas matou todo o ser vivo, como lhe tinha ordenado o Senhor Deus de Israel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 41, 'desde Cadesbarne até Gaza. Toda a terra de Gozen até Gabaon,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 42, 'todos os seus reis e todos os seus países, os tomou e devastou duma só expedição, porque o Senhor Deus de Israel combateu por ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 43, 'Depois voltou com todo o Israel para o lugar onde estava o acampamento em Galgala.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 1, 'Tendo Jabin, rei de Asor, ouvido estas coisas, enviou (mensageiros) a Jobab, rei de Madon, ao rei de Semeron e ao rei de Acsaf,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 2, 'assim como aos reis do norte, que habitavam nas montanhas e na planície, ao meio-dia de Cenerot, aos das campinas e dos territórios de Dor, junto ao mar,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 3, 'ao Cananeu do oriente e do ocidente, ao Amorreu, ao Heteu, ao Fereseu, ao Jebuseu das montanhas, e também ao Heveu, que habitava nas faldas do Hermon na terra de Masfa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 4, 'Todos estes saíram com as suas tropas, multidão tão numerosa como a areia que há sobre as praias do mar, com um número imenso de cavalos e carros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 5, 'Todos estes reis se juntaram perto das águas de Merom para combaterem contra Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 6, 'O Senhor disse a Josué: Não os temas, porque amanhã, a esta mesma hora, tos entregarei a todos para serem passados à espada à vista de Israel; jarretarás os seus cavalos e queimarás os seus carros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 7, 'Josué, com todo o exército, marchou de improviso contra eles, até às águas de Merom, e precipitou-se sobre eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 8, 'O Senhor os entregou nas mãos de Israel, que os derrotou e perseguiu até Sidónia a grande, até às águas de Maserefot e até ao campo de Masfe, que está ao seu lado oriental. Passou-os todos à espada, de sorte que não deixou vivo um só;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 9, 'e fez como o Senhor lhe tinha ordenado: jarretou os seus cavalos e pôs fogo aos seus carros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 10, 'Voltando logo, tomou Asor e matou à espada o seu rei. Asor antigamente tinha o principado sobre todos estes reinos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 11, 'Passou à espada toda a gente que ali morava; não deixou ser vivo algum, mas devastou tudo até ao extermínio e destruiu com um incêndio a própria cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 12, 'Tomou, feriu e devastou as cidades circunvizinhas, e os seus reis, como lhe tinha ordenado Moisés, servo do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 13, 'Israel queimou todas as outras cidades, excepto as que estavam situadas nas colinas e nos lugares elevados; (destas) sòmente Asor, cidade fortíssima, foi consumida pelo fogo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 14, 'Os filhos de Israel, depois de matarem todos os homens, repartiram entre si todos os despojos destas cidades e os gados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 15, 'Como o Senhor tinha ordenado a Moisés seu servo, assim Moisés ordenou a Josué, e este cumpriu tudo; não omitiu nem uma só palavra de todos os mandamentos, que o Senhor tinha dado a Moisés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 16, 'Conquistou, assim, Josué todo o país montanhoso e meridional, a terra de Gosen, a planície, a parte ocidental, o monte de Israel, as suas campinas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 17, 'e a parte do monte que sobe para a banda de Seir até Baalgad sobre a planície do Líbano, na falda do monte Hermon; tomou todos os seus reis, feriu-os e matou-os.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 18, 'Durante muito tempo Josué combateu contra estes reis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 19, 'Não houve cidade que se rendesse (espontâneamente) aos filhos de Israel, excepto o Heveu, que habitava em Gabaon; todas as outras as tomaram à força de armas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 20, 'Era desígnio do Senhor que os seus corações se endurecessem, e que combatessem contra Israel, para que Israel os derrotasse, sem compaixão, e os destruísse, como o Senhor o tinha ordenado a Moisés. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 21, 'Naquele tempo Josué acometeu e matou os Enacins (gigantes) das montanhas de Hebron, de Dabir, de Anab, de todas as montanhas de Judá e de Israel, e destruiu as suas cidades.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 22, 'Não deixou um só da raça dos Enacins na terra dos filhos de Israel, excepto sòmente os que ficaram nas cidades de Gaza, de Get e de Azoto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 23, 'Conquistou pois Josué todo o país, conforme o Senhor tinha dito a Moisés, e entregou a sua posse aos filhos de Israel por porções segundo as suas tribos. E cessou a guerra no país.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 1, 'Estes são os reis que os filhos de Israel derrotaram, e cujas terras possuíram da banda de além do Jordão, para o nascente, desde a torrente de Arnon até ao monte Hermon, e toda a região oriental, que olha para o deserto: (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 2, 'Scon, rei dos Amorreus, que habitava em Hesebon, e reinava desde Aroer, (cidade) que está situada sobre a margem da torrente de Arnon, e desde o meio do vale, sobre metade de Galaad, até à torrente de Jaboc, que é a fronteira dos filhos de Amon;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 3, 'e desde o deserto até ao mar de Cenerot para o nascente, e até ao mar do deserto, que é o Mar Salgado, para o lado oriental pelo caminho que vai a Betsimot; e desde a parte meridional, que está abaixo de Asedot, até Fasga. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 4, 'Os confins de Og, rei de Basan, que tinha ficado dos Befains, e habitou em Astarot e em Edrai, e que reinou no monte Hermon, em Saleca, e em todo o território de Basan, até aos confins'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 5, 'de Gessuri, de Macati e de metade de Galaad, que eram os confins de Seon, rei de Hesebon.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 6, 'Moisés, servo do Senhor, e os filhos de Israel derrotarram-nos, e Moisés deu a posse das suas terras aos Rubenitas, aos Gaditas e aos da meia tribo de Manassés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 7, 'Estes são os reis do país, que Josué e os filhos de Israel derrotaram da banda de além do Jordão para o poente, desde Baalgad, na campina do Líbano, até à montanha escalvada que se eleva para a banda de Seir; e Josué deu esta parte em possessão às tribos de Israel, a cada uma a sua parte,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 8, 'tanto nas montanhas, como nas planícies e campinas, no deserto e no meio-dia, onde habitavam o Heteu, o Amorreu, o Cananeu, o Fereseu, o Heveu e o Jebuseu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 9, '(Os tais reis são): um rei de Jericó; um rei de Hai, que está ao lado de Betel;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 10, 'um rei de Jerusalém; um rei de Hebron;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 11, 'um rei de Jerimot; um rei de Laquis;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 12, 'um rei de Eglon; um rei de Gazer;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 13, 'um rei de Dabir; um rei de Gader;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 14, 'um rei de Herma; um rei de Hered ;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 15, 'um rei de Lebna; um rei de Odulão;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 16, 'um rei de Maceda; um rei de Betei;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 17, 'um rei de Tafua; um rei de Ofer;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 18, 'um rei de Afec; um rei de Saron;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 19, 'um rei de Madon; um rei de Asor;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 20, 'um rei de Semerom; um rei de Aesaf;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 21, 'um rei de Tenac; um rei de Magedo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 22, 'um rei de Cades; um rei de Jacanan do Carmelo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 23, 'um rei de Dor e da província de Dor; um rei das nações de Galgai;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 24, 'um rei de Tersa. Ao todo, trinta e um reis.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 1, 'Josué estava velho, avançado em anos, e o Senhor disse-lhe: Tu estás velho, de muita idade, e resta um dilatadíssimo espaço de terra, que ainda não foi repartido por sorte (nem conquistado),'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 2, 'a saber: o território dos Filisteus, toda a terra de Gessuri,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 3, 'desde o rio turvo, que rega o Egipto, até aos confins de Acaron, para o norte, que deve ser reputada terra de Canaan; os (territórios pertencentes aos) cinco príncipes dos Filisteus: o de Gaza, o de Azoto, o de Ascalon, o de Get e o de Acaron; (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 4, 'os Heveus, ao meio-dia; toda a terra de Canaan, e Maara dos Sidónios, até Afeca e aos confins do Amorreu;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 5, 'a terra dos Gebalitas e todo o território do Líbano, a oriente, desde Baalad na raiz do monte Hermon, até à entrada de Hamath;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 6, 'a terra, daqueles que habitam na Montanha, desde o Líbano até às águas de Maserefot, todos os Sidónios. Sou eu que os hei-de exterminar, diante dos filhos de Israel. Entre pois (todo este terreno) na parte da herança de Israel, como eu te ordenei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 7, 'E agora reparte a terra, que devem possuir as nove tribos e a meia tribo de Manassés;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 8, 'a outra meia tribo e as tribos de Buben e Gad tomaram já posse da terra, que lhes deu Moisés, servo do Senhor, na outra banda do Jordão, para o oriente,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 9, 'desde Aroer, que está situada na margem da torrente de Arnon e desde a cidade que está no meio do vale, toda a campina de Medaba, até Dibon;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 10, 'e todas as cidades de Seon, rei dos Amorreus, que reinou em Hesebon, até aos confins dos filhos de Amon;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 11, 'e Galaad e os territórios de Gessuri e de Macati, todo o monte Hermon, todo o Basan, até Saleca,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 12, 'todo o reino de Og em Basan, o qual reinou em Astarot e em Edrai, e foi o resto dos Befains que ficaram, aos quais Moisés derrotou e destruiu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 13, 'Os filhos de Israel não quiseram exterminar os de Gessuri e de Macati, e assim eles ficaram habitando no meio de Israel até ao dia de hoje.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 14, 'À tribo de Levi porém (Moisés) não deu possessão alguma, porque os sacrifícios e as vítimas do Senhor Deus de Israel são a sua herança, como (o Senhor) lho tinha dito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 15, 'Moisés havia dado a sua parte à tribo dos filhos de Ruben, segundo as suas famílias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 16, 'Os seus confins foram desde Aroer, que está situada sobre a margem da torrente de Arnon, e desde a cidade que está no meio do vale da mesma torrente, toda a planície que vai até Medaba,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 17, 'e Hesebon com todas as suas aldeias, que estão na planície; e também Dibon, Bamotbaal, a cidade de Baalmaou,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 18, 'Jassa, Cedimot, Mefaat,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 19, 'Cariataim, Sabama, Saratasar no monte do vale,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 20, 'Betofogor e Asedot, Fasga e Betiesimot,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 21, 'todas as cidades da planície, e todos os reinos de Seon, rei dos Amorreus, que reinou em Hesebon, a quem Moisés derrotou com os príncipes de Madiang: Hevi, Recem, Sur, Hur, Rebe, tributários de Seon, que habitavam aquele país.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 22, 'Os filhos de Israel mataram também à espada, como a todos os outros, o adivinho Balaão filho de Beor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 23, 'Assim, o rio Jordão ficou sendo o limite dos filhos de Ruben. Estas são as cidades e aldeias que possuem os rubenitas, segundo as suas famílias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 24, 'Moisés deu também à tribo de Gad e aos seus filhos, segundo as suas famílias, a terra que deviam possuir, que é a seguinte:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 25, 'Jazer, todas as cidades de Galaad, metade do país dos filhos de Amon, até Aroer, que está defronte de Raba,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 26, 'desde Hesebon até Ramot, Masfe e Betonim, e desde Manain até aos confins de Dabir;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 27, 'e, no vale, Betaran, Betnemra, Socot e Safon, resto do reino de Seon, rei de Hesebon; o Jordão e os seus territórios até à extremidade do mar de Cenerot, na outra banda do Jordão para o nascente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 28, 'Esta é a parte, as cidades e aldeias dos filhos de Gad, segundo as suas famílias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 29, 'Deu também à meia tribo de Manassés, aos seus filhos, segundo as suas famílias, a sua parte,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 30, 'a qual compreendia, começando em Manain, todo o Basan, e todos os reinos de Og, rei de Basan, e todas as aldeias de Jair, que estão em Basan, (ao todo) sessenta povoações;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 31, 'metade de Galaad, e Astarot e Edrai, cidades do reino de Og em Basan; (deu isto) aos filhos de Maquir, filho de Manassés, isto é, à metade dos filhos de Maquir, segundo as suas famílias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 32, 'Estas são as partes que Moisés distribuiu nas campinas de Moab, na outra banda do Jordão, defronte de Jericó, para o nascente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 33, 'Porém à tribo de Levi não deu possessão alguma, porque o Senhor Deus de Israel é a sua herança, como (o Senhor) lho tinha dito.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 1, 'Eis o que os filhos de Israel possuíram na terra de Canaan, que lhes deram o sacerdote Eleázaro, e Josué, filho de Nun, e os chefes das famílias, de cada tribo de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 2, 'Tudo foi distribuído por sorte pelas nove tribos e meia, como o Senhor tinha mandado por meio de Moisés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 3, 'Às outras duas tribos e meia tinha Moisés dado a sua herança na outra banda do Jordão, não se contando os Levitas, que não receberam porção alguma de terra entre seus irmãos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 4, 'sendo postos em seu lugar Manassés o Efraim, filhos de José, divididos em duas tribos. Os Levitas não receberam outra parte na terra, senão as cidades para habitarem, e os arrabaldes delas para sustentarem os seus animais e rebanhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 5, 'O que o Senhor tinha ordenado a Moisés, cumpriram-no os filhos de Israel, e repartiram a terra (de Canaan).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 6, 'Nesta ocasião os filhos de Judá apresentaram-se a Josué em Galgala. Caleb, filho de Jefone Cenezeu, disse-lhe: Tu sabes o que o senhor disse de mim e de ti a Moisés, homem de Deus, em Cadesbarne.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 7, 'Eu tinha quarenta anos quando Moisés, servo do Senhor, me mandou de Cadesbarne para reconhecer a terra, e eu referi-lhe o que me parecia verdade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 8, 'Porém meus irmãos, que tinham ido comigo, fizeram desanimar o povo. Não obstante isto, segui o Senhor meu Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 9, 'Naquele dia, Moisés fez-me este juramento: A terra que o teu pé calcou será tua herança e de teus filhos para sempre, porque seguiste o Senhor meu Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 10, 'O Senhor, pois, me conservou a vida até ao presente dia, como prometeu. Há quarenta e cinco anos que o Senhor disse aquela palavra a Moisés, quando Israel andava pelo deserto; hoje tenho oitenta e cinco anos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 11, 'e acho-me tão robusto como no tempo em que fui enviado a reconhecer a terra; o vigor, que eu tinha então, dura em mim até hoje, tanto para combater como para andar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 12, 'Dá-me, pois, este monte, que o Senhor me prometeu, ouvindo-o tu mesmo, no qual há (ainda) Enacins, e cidades grandes e fortificadas; o Senhor seja comigo, e eu possa exterminá-los, como ele me prometeu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 13, 'Josué abençoou-o e deu-lhe Hebron como herança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 14, 'Desde então Hebron foi de Caleb, filho de Jefone Cenezeu, até ao dia de hoje, por ter seguido o Senhor Deus de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 15, 'Hebron chamava-se outrora Cariat-Arbe. Arbe foi o maior entre os Enacins. E a terra (de Canaan) repousou (por então) de guerras.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 1, 'A parte que tocou por sorte aos filhos de Judá, segundo as suas famílias, foi esta: Desde a fronteira de Edom, até ao deserto de Sin, para o meio-dia, e até à extremidade da região meridional (de Canaan).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 2, 'A sua fronteira meridional ia desde a ponta do Mar de Sal, da língua que ele forma para o meio-dia,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 3, 'e estendia-se para a subida do Escorpião, passava a Sina, subia para Cadesliarne, passava em Esron, subindo para Adar e dando volta a Carcaa,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 4, 'e, passando dali para Asrnona, chegava até à torrente do Egipto e terminava no Mar Grande. Estes os seus limites, pelo lado do meio-dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 5, 'Pela parte do oriente, a fronteira foi o Mar do Sal, até à extremidade do Jordão. Pela parte do norte, a fronteira ia desde a língua que o mar forma até até ao mesmo rio Jordão,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 6, 'e subia a Bet Hagla, passava ao norte de Bet Araba, subindo à Pedra de Boen, filho de Ruben,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 7, 'seguia até aos confins de Debera, desde o vale de Acor para o norte, olhando para Galgala, que está defronte da subida de Adomim, pela parte austral da torrente; (depois) passava as águas, que se chamam fonte do Sol, e terminava na fonte de Rogel;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 8, 'dali subia pelo vale do filho de Enom, pela banda meridional do Jebuseu, onde está Jerusalém; daí ia para cima até ao cume do monte, que está fronteiro a Geenom, para o ocidente, na extremidade do vale dos Refains para o norte;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 9, 'desde o cume do monte estendia-se até à fonte de Neftoa e chegava até às aldeias do monte Efron; baixava depois para Baala, que é Cariatiarim, isto é, a cidade dos Bosques;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 10, 'de Baala dava volta para o ocidente até ao monte Seir, e ladeava o monte Jarim ao norte para a banda de Queslon; descia a Betsames, passava por Tamna'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 11, 'até o lado setentrional de Acaron; declinava para Secrona e passava o monte Baala; estendia-se até Jebneel e terminava, pelo lado ocidental, no Mar Grande.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 12, 'Estes são, por todos os lados, os limites dos filhos de Judá segundo as suas famílias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 13, 'A Caleb, filho de Jefone, se havia dado uma parte, no meio dos filhos de Israel, consoante o Senhor mandara a Josué, a saber, a cidade de Arbe, pai de Enac, que é (actualmente chamada) Hebron.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 14, 'Caleb exterminou dela os três filhos de Enac: Sesai, Aiman e Tolmaí, da raça de Enac.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 15, 'Subindo dali, marchou para os habitantes de Dabir, que antes se chamava Cariat-Sefer, isto é, cidade das letras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 16, 'E Caleb disse: Eu darei minha filha Axa por mulher àquele que assaltar e tomar Cariat-Sefer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 17, 'Tomou-a Otoniel, filho de Cenez, irmão mais novo de Caleb; e Caleb deu-lhe sua filha Axa por mulher.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 18, 'Esta, enquanto iam caminhando juntos, foi aconselhada por seu marido que pedisse a seu pai um campo. Ao descer do jumento, Caleb disse-lhe: Que tens ?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 19, 'Ela respondeu: Dá-me uma bênção; tu deste-me uma terra ao meio-dia e sêca; junta-lhe outra de regadio. Deu-lhe pois Caleb uma terra, que se regava nos altos e nos baixos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 20, 'Esta é a herança da tribo dos filhos de Judá, segundo as suas famílias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 21, 'As cidades dos filhos de Judá, nas extremidades meridionais, pelas fronteiras da Idumeia, eram: Cabseel, Eder, Jagur,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 22, 'Cina, Dimona, Adada,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 23, 'Cades, Asor, Jetnam,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 24, 'Zif, Telem, Balot,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 25, 'Asor-a-Nova, Cariot, Hesron, que é Asor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 26, 'Amam, Sama, Molada,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 27, 'Asergada, Hassemon, Betfelet,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 28, 'Hasersnal, Bersabee, Baziotia,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 29, 'Baala, Jim, Esem,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 30, 'Eltolad, Cesil, Harma,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 31, 'Siceleg, Medemena, Sensena,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 32, 'Lebaot, Selim, Aen e Bemon. Ao todo, vinte e nove cidades com as suas aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 33, 'Nas campinas: Estaol, Sarea, Asena,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 34, 'Zanoe, Enganim, Tafua, Enaim,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 35, 'Jerimot, Adulam, Soco, Azeca,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 36, 'Saraim, Aditaim, Gedera, Qederotaim: catorze cidades com as suas aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 37, 'Sanan, Hadassa, Magdalgad,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 38, 'Delean, Masefa, Jectel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 39, 'Laquis, Baseat, Eglon,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 40, 'Quebon, Leemau, Cetlis,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 41, 'Giderot, Betdagon, Naama, Maceda: dezasseis cidades com as suas aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 42, 'Labana, Eter, Asan,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 43, 'Jefta, Esna, Nesib,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 44, 'Ceila, Aezib, Maresa: nove cidades com as suas aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 45, 'Acaron com as suas aldeias e lugarejos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 46, 'De Acaron até ao mar: todo o país que olha para a banda de Azoto e suas aldeias;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 47, 'Azoto com as suas aldeias e lugarejos; Gaza com as suas aldeias e lugarejos, até à torrente do Egipto e ao Mar Grande, que é o seu limite.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 48, 'Nos montes: Samir, Jeter, Socot,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 49, 'Dana, Cariatsena, que é Dabir,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 50, 'Anab, Istemo, Anim,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 51, 'Gosen, Olon, Gilo: onze cidades com as suas aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 52, 'Arab, Ruma, Esaan,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 53, 'Janum, Bettafua, Afeca,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 54, 'Atmata, Cariat-Arbe, que é Hebron, e Sior: nove cidades com as suas aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 55, 'Maon, Carmel, Zif, Jota,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 56, 'Jezrael, Jucadam, Zanoe,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 57, 'Acain, Gabaa, Tamna: dez cidades com as suas aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 58, 'Halhul, Bessur, Gedor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 59, 'Meret, Betanot, Elteeon: seis cidades com as suas aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 60, 'Cariatbaal, que é Cariatiarim, cidade dos Bosques, e Areba: duas cidades com as suas aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 61, 'No deserto: Bet-aranha, Medin, Secaca,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 62, 'Nebsan, e a cidade do Sal, e Engadi: seis cidades com as suas aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 63, 'Ao Jebuseu, que habitava em Jerusalém, não o puderam exterminar os filhos de Judá; e o Jebuseu habitou em Jerusalém, com os filhos de Judá, até ao dia de hoje.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 1, 'A parte que tocou em sorte aos filhos de José foi desde o Jordão, defronte de Jericó, até às águas de Jericó, para o nascente; a seguir, rumo ao deserto que sobe de Jericó ao monte de Betei;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 2, 'a fronteira (depois) vai do Betei a Luza, e passa ao longo dos confins de Arqui, para Atarot;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 3, '(dali) desce pelo ocidente, ao longo dos confins de Jefleti, até aos confins de Bet-horon inferior e de Gazer, e termina no Mar Grande.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 4, 'Foi isto que possuíram os filhos de José, Manassés e Efraim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 5, 'A fronteira dos filhos de Efraim, segundo as suas famílias, o limite da sua herança, para o nascente, foi Atarot-adar até Bet-horon superior.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 6, 'Os seus confins estendem-se até ao mar, do lado de Macmetat, que olha para o norte, dão volta pelo oriente para Tanatselo, e passa desde o oriente até Janoe;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 7, 'de Janoe desce até Atarot e Naarata, vai a Jericó e termina no Jordão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 8, 'De Tafa passa para a banda do mar até ao vale do Cana e termina no mar. Esta é a possessão da tribo dos filhos de Efraim, segundo as suas famílias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 9, 'Foram separadas cidades com as suas aldeias para os filhos de Efraim no meio da possessão dos filhos de Manassés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 10, 'Os filhos de Efraim não exterminaram o Cananeu, que habitava em Gazer, e o Cananeu habitou até ao dia de hoje no meio de Efraim como tributário.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 1, 'Esta é a parte que tocou por sorte à tribo de Manassés, porque foi o primogênito de José. Maquir, primogênito de Manassés e pai de Galaad, que foi um homem guerreiro, possuiu o país de Galaad e de Basan;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 2, 'também foi dado (um pedaço de terra) aos restantes filhos de Manassés, segundo as suas famílias, aos filhos de Abiezer, aos filhos de Helec, aos filhos de Esriel, aos filhos de Sequem, aos filhos de Hefer, aos filhos de Semida: estes são os filhos varões de Manassés, filho de José, segundo as suas famílias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 3, 'Salfaad filho de Hefer, filho de Galaad, filho de Maquir, filho de Manassés, não teve filhos, mas sòmente filhas, cujos nomes são estes: Maala, Noa, Hegla, Melca, e Tersa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 4, 'Estas apresentaram-se diante do sacerdote Eleázaro e diante de Josué, filho de Nun, e diante dos príncipes, dizendo: O Senhor ordenou por meio de Moisés que nos fosse dada uma herança no meio de nossos irmãos. (Josué) deu-lhes uma possessão no meio dos irmãos de seu pai, conforme a ordem do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 5, 'Tocaram a Manassés dez partes, além da terra de Galaad e de Basan, na outra banda do Jordão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 6, 'As (cinco) filhas de Manassés possuíram a sua herança no meio dos filhos desta tribo. A terra de Galaad coube em sorte aos outros filhos de Manassés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 7, 'O limite de Manassés foi desde Aser até Macmetat, que olha para Siquem, e se estende pela direita até perto dos que habitam a fonte Tafua.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 8, 'Na sorte de Manassés tinha caído o território de Tafua, o qual está perto dos confins de Manassés, e é dos filhos de Efraim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 9, 'A fronteira desce ao vale do Cana para o meio-dia da torrente; as cidades desta região, que souberam por sorte a Efraim, estão no meio das cidades de Manassés; o limite de Manassés passa pelo norte da torrente e vai terminar na mar;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 10, 'assim a possessão de Efraim está ao meio-dia, a de Manassés ao norte, e ambas ficam cerradas pelo mar, e se encontram com a tribo de Aser pelo norte, e a tribo de Issacar pelo nascente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 11, 'Manassés teve por herança (nos territórios) de Issacar e de Aser, Betasan com as suas aldeias, Johlaam com as suas aldeias, os habitantes de Dor com as suas aldeias, os habitantes de Endor com as suas aldeias, os habitantes de Tenac com as suas aldeias, Magedo com as suas aldeias; e a terça parte da cidade de Nofet.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 12, 'Os filhos de Manassés não puderam destruir estas cidades, e o Cananeu conseguiu continuar a habitar esta sua terra (juntamente com eles).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 13, 'Porém, depois que os filhos de Israel se tornaram mais fortes, sujeitaram os Cananeus e fizeram-nos seus tributários, mas não os mataram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 14, 'Os filhos de José disseram a Josué: Por que me deste tu a posse de uma só herança e de uma só parte, sendo eu um povo tão numeroso, e tendo-me o Senhor abençoado?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 15, 'Josué disse-lhes: Se tu és um povo tão numeroso sobe ao bosque e corta para ti espaço no país dos Fereseus e dos Rafeins, já que a possessão do monte de Efraim é muito estreita para ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 16, 'Os filhos de José responderam-Ihe: A montanha não nos basta, e os Cananeus, que habitam a planície, onde está Betsan com as suas aldeias, e Jezrael que ocupa a meio do vale, usam carros armados de ferro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 17, 'Josué disse à casa de José, Efraim e Manassés: Tu és um povo muito numeroso e de grande força, não terás só uma parte,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 18, 'mas passarás ao monte, cortarás para ti, e limparás maior terreno para habitares; poderás alargar-te ainda mais, depois que tiveres exterminado o Cananeu, apesar de ele ter carros armados de ferro, e ser fortíssimo.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 1, 'Todos os filhos de Israel se juntaram em Silo, e levantaram ali o tabernáculo da reunião. A terra estava-lhes sujeita.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 2, 'Havia sete tribos dos filhos de Israel, que ainda não tinham recebido as suas possessões.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 3, 'Josué disse-lhes: Até quando vos consumirá o ócio, até quando sereis negligentes em tomar posse da terra que o Senhor Deus de vossos pais vos deu?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 4, 'Escolhei três homens de cada tribo, para que eu os envie e vão dar uma volta pelo país, façam a sua demarcação, segundo o número de cada multidão (ou tribo que a deve possuir), e me refiram a demarcação que tiverem feito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 5, 'Dividi entre vós a terra em sete partes; Judá fique nos seus limites da banda do meio-dia, e a casa de José da banda do setentrião.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 6, 'A terra intermédia dividi-a em sete partes; depois vireis aqui ter comigo, para que eu aqui na presença do Senhor vosso Deus vos lance as sortes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 7, 'Os Levitas não têm entre vós parte alguma, mas a sua herança é o sacerdócio do Senhor. Gad, Ruben e a meia tribo de Manassés, já receberam as suas porções do outro lado do Jordão ao nascente, as quais lhes deu Moisés, servo do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 8, 'Quando aqueles homens se levantaram para ir fazer a demarcação da terra, Josué deu-lhes esta ordem: Dai volta à terra, demarcai-a, voltai a mim, para que eu vos lance as sortes aqui em Silo diante do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 9, 'Partiram pois, e, conhecendo-a cuidadosamente, dividiram-na em sete partes, que descreveram num livro. E voltaram a Josué no acampamento de Silo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 10, 'Ele lançou as sortes diante do Senhor, em Silo, e dividiu a terra em sete partes entre os filhos de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 11, 'Caiu a primeira sorte aos filhos de Benjamim, segundo as suas famílias, para possuirem o país situado entre os filhos de Judá e os filhos de José.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 12, 'A sua fronteira para a banda do setentrião parte do Jordão, estendendo-se para a banda setentrional de Jericó, e dai sobe às montanhas para o poente, chega até ao deserto de Betaven,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 13, 'passa ao meio-dia perto de Luza, chamada também Betei, desce a Atarot-Adar, perto do monte, que está ao meio-dia de Bet-horon inferior,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 14, 'e, dando volta, declina para o mar ao meio-dia do monte, olha para Bet-horon para o Áfrico , e termina em Cariat-baal, que também se chama Cariatiarim, cidade dos filhos de Judá. Esta é a fronteira para o mar, pelo poente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 15, 'Pelo meio-dia, a sua fronteira vai da parte de Cariatiarim pra o mar, e chega até à fonte das águas de Neftoa;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 16, '(em seguida) desce até àquela parte do monte, que olha para o vale dos filhos de Enom, e que está ao setentrião, na extremidade do vale dos Befains; depois desce a Geenom (isto é, ao vale de Enom) ao lado do Jebuseu, pelo meio-dia, e chega até à fonte de Rogel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 17, 'passando para o norte, e estendendo-se até Ensemes, isto é, a fonte do Sol;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 18, 'passa depois até aos cabeços, que estão defronte da subida de Adomim, e desce a Abendoen, isto é, a pedra de Boen, filho de Ruben, passa pelo lado do norte até à campina e desce à planície;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 19, 'depois avança para o setentrião, além de Bet-hagla, e termina na ponta setentrional do Mar do Sal, na embocadura do Jordão, que olha para o meio-dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 20, 'O Jordão é o seu limite pelo oriente. Esta é a herança dos filhos de Benjamim, segundo os seus limites à roda, e segundo as suas famílias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 21, 'As suas cidades foram: Jericó, Bet-hagla, o vale de Casis,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 22, 'Bet-Araba, Samaraim, Betel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 23, 'Avim, Pará, Ofera,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 24, 'a cidade de Emona, Ofni e Gabee: doze cidades com as suas aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 25, 'Gabaon, Rama, Berot,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 26, 'Mesfe, Cafara, Amosa,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 27, 'Reeem, Jarefel, Tarela,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 28, 'Sela, Elef, Jebus, que é Jerusalém, Gabaat e Cariat: catorze cidades com as suas aldeias. Esta é a herança dos fiIhos de Benjamim, segundo as suas famílias.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 1, 'Caiu a segunda sorte aos filhos de Simeão, segundo suas famílias. A herança'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 2, 'deles foi no meio da possessão dos filhos de Judá: Bersabec, Sabee, Molada,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 3, 'Hasersual, Bala, Asem,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 4, 'Eltolad, Betul, Harma,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 5, 'Siceleg, Betmarcabot, Hasersusa,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 6, 'Betlebaot e Saroen: treze cidades com as suas aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 7, 'Ain, Remon, Atar e Asan: quatro cidades com as suas aldeias,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 8, 'assim como todos os lugarejos dos arredores desta cidades até Baalat Beer, que é a Ramat do meio-dia. Esta é a herança dos filhos de Simeão, segundo as suas famílias,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 9, 'na possessão e no território dos filhos de Judá, porque era grande demais (para os filhos de Judá) e, por isso, os filhos de Simeão tiveram a sua possessão no meio da herança daqueles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 10, 'A terceira sorte caiu aos filhos de Zabulon, segundo as suas famílias. A fronteira da sua herança estende-se até Sarid;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 11, 'sobe para ocidente, até Merala, e chega a Debaset, até à torrente, que está defronte de Jeconan;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 12, 'volta de Sarid para o nascente até aos confins de Ceselettabor; avança a Daberet, e sobe para Jafie;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 13, 'dali passa até ao lado oriental de Get-hefer e de Tacasin e estende-se até ao Remon, Amtar e Noa;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 14, 'dá volta, pelo norte, para Haraton, e termina no vale de Jeftael,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 15, 'Catet, Naalol, Semeron, Jerala e Belém: doze cidades com as suas aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 16, 'Esta é a herança da tribo dos filhos de Zabulon, segundo as suas famílias, com as suas cidades e aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 17, 'A quarta sorte caiu a Issacar, segundo as suas famílias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 18, 'E a sua herança foi: Jezrael, Casalot, Suném,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 19, 'Hafaraim, Seon, Anaarat,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 20, 'Rabot, Cesion, Abes,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 21, 'Ramet, Enganim, Enada e Betfeses.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 22, 'A sua fronteira chega até ao Tabor e Saesima e Betsames, e termina no Jordão: dezasseis cidades com as suas aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 23, 'Esta é a herança dos filhos de Issacar, segundo as suas famílias, com as suas cidades e aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 24, 'A quinta sorte caiu à tribo dos filhos de Aser, segundo as suas famílias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 25, 'O seu território foi: Halcat, Cali, Beten, Axaf,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 26, 'Elmelec, Amaad e Messal; a fronteira chega até ao Carmelo do mar e a Sior e a Labanat;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 27, 'volta pelo oriente para a banda de Betdagon, passa por Zabulon e pelo vale de Jeftael, para o norte, até Betemee e Neiel; estende-se pela esquerda até Cabul,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 28, 'Abran, Roob, Hamon e Cana, até Sidónia, a grande;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 29, 'volta para Horma até à fortíssima cidade de Tiro, e até Hosa; e termina no mar, perto do território de Achziba;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 30, '(abrange também) Ama, Afec e Boob: vinte e duas e cidades com as suas aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 31, 'Esta é a herança dos filhos de Aser, segundo as suas famílias, e estas são as suas cidades e aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 32, 'A sexta sorte caiu aos filhos de Neftali, segundo as suas famílias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 33, 'A sua fronteira começa em Helef e Elon, vai a Saananim e a Adami, chamada também Neceb, e a Jebnael até Lecum, e avança até ao Jordão;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 34, 'volta para o ocidente até Azanottabor, dali estende-se até Hucuca, passa por Zabulon, pela parte do meio-dia, por Aser, pelo ocidente, e por Judá para o Jordão, pelo oriente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 35, 'Suas cidades fortificadíssimas (são) Assedim, Ser, Emat, Becat, Ceneret,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 36, 'Edema, Arama, Asor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 37, 'Cedes, Edrai, Enasor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 38, 'Jeron, Magdalel, Horem, Betanat e Betsames: dezanove cidades com as suas aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 39, 'Esta é a herança da tribo dos filhos de Neftali, segundo as suas famílias, e estas são as suas cidades e aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 40, 'A sétima sorte caiu à tribo dos filhos de Dan, segundo as suas famílias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 41, 'O limite da sua herança compreendia Sara, Estaol, Hirsemes, isto é, a cidade do Sol,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 42, 'Selebin, Ajalon, Jetela,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 43, 'Elon, Temna, Aeron,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 44, 'Eltece, Gebbeton, Balaat,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 45, 'Jud, Bane, Barac, Getremmon,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 46, 'Merjarcon e Arecon, com os confins que olham para Jope.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 47, 'Aqui termina esta possessão. Todavia os filhos de Dan subiram a pelejar contra Lesem, tomaram-na e passaram-na ao fio de espada. Tomada posse dela, habitaram-na, chamando-lhe Dan, do nome de Dan, seu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 48, 'Esta é a herança da tribo dos filhos de Dan, segundo as suas famílias, e estas são as suas cidades e aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 49, 'Tendo Josué acabado de repartir a terra por sorte por cada uma das tribos, os filhos de Israel deram a Josué, filho de Nun, por herança, no meio deles,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 50, 'segundo o preceito do Senhor, a cidade que ele pediu, Tamnat Saraa, sobre o monte de Efraim. Josué reedificou a cidade e habitou nela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 51, 'Estas são as heranças, que o sacerdote Eleázaro, e Josué, filho de Nun, e os chefes de família das tribos dos filhos de Israel distribuiram por sorte em Silo, diante do Senhor, à porta do tabernáculo da reunião. E assim acabaram a partilha da terra (de Canaan).');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 1, 'O Senhor falou a Josué, dizendo: Fala aos filhos de Israel e diz-lhes:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 2, 'Separai as cidades para os fugitivos, das quais vos falei por meio de Moisés,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 3, 'a fim do que se refugie nelas todo o que matar uma pessoa, sem querer, e possa evitar a ira do vingador do sangue.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 4, 'Quando ele se refugiar em uma destas cidades, apresentar-se-á à porta da cidade e exporá aos anciães dela tudo o que possa comprovar a sua inocência; deste modo o receberão, e lhe darão lugar em que habite.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 5, 'Se aquele, que quer vingar o morto, o perseguir, não lho entregarão às suas mãos, porque matou por ignorância o seu próximo, sem que antes fosse seu inimigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 6, 'Habitará nesta cidade, até que compareça em juízo, para dar conta do que fez e até que morra o sumo sacerdote, que estiver (em exercício) naquele tempo. Então voltará o homicida, e entrará na sua cidade e na sua casa, donde tinha fugido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 7, '(Consequentemente) decretaram (que fossem cidades de refúgio) Cedes na Galileia, sobre o monte de Neftali, e Siquem sobre o monte de Efraim, e Cariatarbe, que é Hebron, sobre o monte de Judá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 8, 'Na outra banda do Jordão, para o nascente de Jericó, destinaram Bosor, que está situada na planície do deserto, da tribo de Buben, e Ramot em Galaad, da tribo de Gad, e Gaulon em Basan, da tribo de Manassés.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 1, 'Os príncipes da família de Levi foram ter com o sacerdote Eleázaro, e com Josué filho de Num, e com os chefes das famílias de cada tribo dos filhos de Israel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 2, 'e falaram-lhes em Silo, na terra de Canaan, dizendo: O Senhor ordenou, por meio de Moisés, que nos fossem dadas cidades em que habitássemos, e os arrabaldes delas para manter os nossos animais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 3, 'E os filhos de Israel deram das suas possessões cidades com os seus arrabaldes, conforme o mandamento do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 4, 'E sairam por sorte à família de Caat, para os filhos do sacerdote Aarão, treze cidades das tribos de Judá, de Simeão e de Benjamim;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 5, 'aos outros filhos de Caat, isto é, aos Levitas que restavam, dez cidades das tribos de Efraim, de Dan, e da meia tribo Manassés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 6, 'Aos filhos de Gerson saiu a sorte de receberem treze cidades das tribos de Issacar, de Aser, de Neftali, e da meia tribo de Manassés, em Basan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 7, 'Aos filhos de Merari segundo as suas famílias, doze cidades das tribos de Ruben, de Gad e de Zabulon.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 8, 'Os filhos de Israel deram estas cidades e os seus arrabaldes aos Levitas, como o Senhor tinha mandado por meio de Moisés, distribuindo-as a cada um por sorte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 9, 'Josué deu as cidades das tribos dos filhos de Judá e de Simeão, cujos nomes são (isto é, vão ser apontados) :'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 10, 'aos filhos de Aarão da família de Caat, da linhagem de Levi (pois que a eles saiu a primeira sorte),'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 11, 'Cariatarbe, (cidade) do pal de Enac, que (actualmente) se chama Hebron, sobre o monte de Judá, com os seus arrabaldes em roda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 12, 'Os seus campos e aldeias tinha-os dado (Josué), por herança, a Caleb, filho de Jefone.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 13, 'Deu, pois, aos filhos do sacerdote Aarão, Hebron, cidade de refúgio, com os seus arrabaldes, Lobna com os seus arrabaldes,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 14, 'Jeter, Estemo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 15, 'Holon, Dabir,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 16, 'Ain, Jetae Betsames, com os seus arrabaldes: nove cidades de duas tribos, como fica dito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 17, 'Da tribo do filhos de Benjamim (deu) Gabaon, Gabae,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 18, 'Anatot e Ahmon, com os seus arrabaldes: quatro cidades.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 19, 'Ao todo são treze as cidades dos filhos do sacerdote Aarão, com os seus arrabaldes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 20, 'Aos outros filhos de Caat, da linhagem de Levi, segundo as suas famílias as cidades que lhes couberam, por sorte, eram da tribo de Efraim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 21, 'Deram-lhes a cidade de refúgio Siquem, com os seus arrabaldes sobre o monte de Efraim, e Gazer,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 22, 'Cibsaim e Bet-horon, com os seus arrabaldes: quatro cidades.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 23, 'Da tribo de Dan, Elteco e Gabaton,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 24, 'Ajalon e Gettemon, com os seus arrabaldes: quatro cidades.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 25, 'Da meia tribo de Manassés, Tanac e Getremon, com os seus arrabaldes: duas cidades.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 26, 'Ao todo, foram dadas aos outros filhos de Caat, dez cidades, com os seus arrabaldes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 27, 'Também da meia tribo de Manassés, foram dadas aos filhos de Gerson, da linhagem de Levi, as cidades de refúgio: Gaulon, em Basan, e Bosran, com os seus arrabaldes: duas cidades.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 28, 'Da tribo de Issacar, Cesion, Daberet,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 29, 'Jaramot e Enganim, com os seus arrabaldes: quatro cidades.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 30, 'Da tribo de Aser, Masal, Abdon,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 31, 'Helcat e Roob, com os seus arrabaldes: quatro cidades.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 32, 'Da tibo de Neftali, a cidades de refúgio: Cedes, na Galileia, Hamot-Dor, e Cartan, com os seus arrabaldes: três cidades.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 33, 'Todas as cidades das famílias de Gerson foram treze, com os seus arrabaldes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 34, 'Aos filhos de Merari, ao resto dos filhos de Levi, segundo as suas famílias, foram dadas, da tribo de Zabulon, Jecnam e Carta,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 35, 'Damna, e Naalol: quatro cidades, com o seus arrabaldes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 36, 'Da tribo de Ruben, na banda de além do Jordão, defronte de Jericó, as cidades de refúgio: Bosor, no deserto, Misor, Jaser, Jetson e Mefaat; quatro cidades com os seus arrabaldes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 37, 'Da tribo do Gad, as cidades de refúgio; Bamot, em Galaad, Manaim, Hesbom e Jazer; quatro cidades com os seus arrabaldes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 38, 'Todas as cidades dos filhos de Merari, segundo as suas famílias e casas, foram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 39, 'Pelo que todas as cidades dos Levitas, no meio da possessão dos filhos de Israel, foram quarenta e oito,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 40, 'com os seus arrabaldes, e cada uma foi distribuída segundo as famílias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 41, 'O Senhor Deus deu a Israel toda a terra que tinha prometido com juramento a seus pais que lhes daria, e eles possuíram-na e habitaram nela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 42, 'E deu-lhes paz com todas as nações ao redor, e nenhum dos inimigos ousou resistir-lhes, mas todos ficaram sujeitos ao seu domínio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 43, 'Nem uma só palavra do que tinha prometido dar-lhes ficou sem efeito, mas tudo se cumpriu.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 1, 'Neste mesmo tempo Josué chamou os Rubenitas, os Gaditas, e a meia tribo de Manassés,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 2, 'e disse-lhes: Vós fizestes tudo o que Moisés, servo do Senhor, vos ordenou; também a mim me tendes obedecido em tudo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 3, 'e durante um tão largo tempo até ao dia de hoje não abandonastes os vossos irmãos, observando o mandamento do Senhor vosso Deus. Agora, visto que o Senhor vosso Deus deu repouso e paz aos vossos irmãos, como lho tinha prometido, voltai e ide para as vossas tendas, para a terra que vos pertence, terra que Moisés, servo do Senhor, vos deu da outra banda do Jordão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 5, 'Só vos imponho de que cumprais exactamente o mandamento e a lei que Moisés, servo do Senhor, vos prescreveu, (isto é) que ameis o Senhor vosso Deus, andeis em todos os seus caminhos, observeis os seus mandamentos, estejais unidos a ele, e o sirvais de todo o coração e de toda a vossa alma.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 6, 'Depois deu-lhes Josué a benção e os despediu. Eles voltaram para as suas tendas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 7, 'Ora Moisés tinha dado à meia tribo de Manassés uma possessão em Basan; por isso Josué deu, à outra meia, uma parte entre os outros seus irmãos, na banda de aquém do Jordão, para o ocidente. Reenviando-os para as suas tendas e, tendo-os abençoado,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 8, 'disse-lhes: Vós voltais para vossas casas com muitas riquezas, rebanhos numerosos, com prata e ouro, bronze e ferro, e vestidos de toda a qualidade; reparti com vossos irmãos a presa dos inimigos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 9, 'Os filhos de Ruben e os filhos de Gad, com a meia tribo de Manassés, voltaram, e separaram-se dos filhos de Israel em Silo, que está em Canaan, para entrarem em Galaad, terra da sua possessão, que tinham obtido por meio de Moisés, conforme a ordem do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 10, 'E, tendo chegado aos distritos do Jordão, na terra de Canaan, edificaram junto ao Jordão um altar de imensa grandeza,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 11, 'Tendo ouvido isto os filhos de Israel, e sabido por mensageiros seguros, que os filhos de Ruben, de Gad e da meia tribo de Manassés, tinham edificado um altar na terra de Canaan, nos distritos do Jordão, defronte dos filhos de Israel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 12, 'reuniram-se todos em Silo, para marcharem e combaterem contra eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 13, 'Entretanto enviaram-lhes, à terra de Galaad, Finéas, filho do sacerdote Eleázaro,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 14, 'e com ele dez príncipes, cada um de sua tribo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 15, 'Estes (enviados) foram ter com os filhos de Ruben, de Gad e da meia tribo de Manassés, na terra de Galaad, e disseram-lhes:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 16, 'Estas coisas vos manda dizer todo o povo do Senhor: Que transgressão é esta? Por que abandonastes vós o Senhor Deus de Israel, levantando um altar sacrílego, e apartando-vos do seu culto?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 17, 'Porventura parece-vos pouco o pecado de Beelfegor, do qual ainda hoje não estamos purificados, apesar de, por causa dele, muitos do povo terem perecido?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 18, 'Vós abandonastes hoje o Senhor, e amanhã cairá a sua ira sobre todo o Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 19, 'Se julgais que a terra da vossa herança é impura, passai para a terra em que está o tabernáculo do Senhor, habitai entre nós, contanto que vos não aparteis do Senhor, nem da nossa sociedade, edificando um altar além do altar do Senhor nosso Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 20, 'Não foi assim, por Acan filho de Zaré ter violado o mandamento do Senhor, que a sua ira veio sobre todo o povo de Israel? Ele era um só homem, e oxalá que só ele tivesse perecido por causa do seu crime.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 21, 'Os filhos de Ruben, de Gad e da meia tribo de Manassés, responderam aos chefes da legação de Israel:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 22, 'O Senhor Deus fortíssimo, o Senhor Deus fortíssimo, ele o sabe, e também Israel o compreenderá; se nós com espírito de prevaricação levantamos este altar, ele nos não proteja, mas desde já nos castigue;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 23, 'se o fizemos com intenção de nos afastarmos do Senhor, e oferecer sobre ele holocaustos, oblações e sacrifícios pacíficos, ele mesmo o examine e julgue.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 24, 'Muito pelo contrário: o pensamento e desígnio que tivemos foi porque poderá acontecer que um dia digam os vossos filhos aos nossos: Que tendes vós com o Senhor Deus de Israel?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 25, 'O Senhor pôs o rio Jordão por termo entre nós e vós, ó filhos de Ruben, ó filhos de Gad; e por isso não tendes parte no Senhor. Nesta ocasião os vossos filhos poderiam afastar os nossos do temor do Senhor. Portanto, julgámos que era melhor (proceder assim)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 26, 'e dissemos: Façamos um altar, não para oferecer holocaustos, nem vítimas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 27, 'mas para testemunho entre nós e vós, e entre a nossa posteridade e a vossa, de que servimos ao Senhor e de que temos direito de lhe oferecer holocaustos, sacrifícios e vítimas pacíficas, e para que os vossos filhos não digam amanhã aos nossos filhos: Vós não tendes parte no Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 28, 'Se o quiserem dizer, responder-lhe-ão: Eis o altar do Senhor, que os nossos pais fizeram, não para holocaustos, nem sacrifícios, mas para testemunho entre nós e vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 29, 'Longe de nós este crime que nos apartemos do Senhor, que deixemos de seguir as suas pisadas, edificando um altar para oferecer holocaustos, oblações e sacrifícios, fora do altar do Senhor nosso Deus, que está levantado diante do seu tabernáculo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 30, 'Quando ouviram isto, o sacerdote Finéas e os chefes da legação de Israel, que com ele estavam, apaziguaram-se, e acolheram com grande satisfação as palavras dos filhos de Ruben, de Gad e da meia tribo de Manassés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 31, 'O sacerdote Finéas, filho de Eleázaro, disse-lhes: Agora sabemos que o Senhor está convosco, visto que estais alheios a tal prevaricação, e livrastes os filhos de Israel da mão ( justamente vingadora) do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 32, 'E, deixando os filhos de Ruben e de Gad, voltou com os chefes, da terra de Galaad, nos confins de Canaan, para os filhos de Israel, e deu-lhes conta de tudo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 33, 'O seu falar agradou a todos os que o ouviram. Os filhos de Israel louvaram a Deus, e não falaram mais em sair contra eles para lhes fazer guerra e devastar a terra da sua possessão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 34, 'Os filhos de Ruben e de Gad chamaram ao altar que tinham edificado Ed, porque — (disseram) — é testemunho, para nós, de que Javé é (o verdadeiro) Deus.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 1, 'Passado muito tempo depois que o Senhor tinha dado a paz a Israel, subjugadas todas as nações circunvizinhas, Josué, sendo já velho, de idade muito avançada,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 2, 'chamou todo o Israel, os anciães, os chefes, os juízes e os oficiais, e disse-lhes: Eu estou velho, de idade muito avançada,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 3, 'e vós vedes tudo o que o Senhor vosso Deus fez a todas as nações circunvizinhas, e como ele mesmo combateu por vós;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 4, 'vedes que reparti entre vós por sorte toda a terra, desde a parte oriental do Jordão até ao Mar Grande, e, posto que restem ainda muitas nações (a vencer),'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 5, 'O Senhor vosso Deus as exterminará e as tirará da vossa vista, e vós possuireis o país, como ele vos prometeu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 6, 'Sòmente é preciso que sejais fortes e solícitos em observar todas as coisas que estão escritas no livro da lei de Moisés; não vos desvieis delas, nem para a direita, nem para a esquerda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 7, 'Não vos mistureis com esses povos que ficaram entre vós, não jureis pelo nome dos seus deuses, nem os sirvais, nem os adoreis,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 8, 'mas permanecei unidos ao Senhor vosso Deus, como tendes feito até este dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 9, 'Então o Senhor vosso Deus exterminará à vossa vista nações grandes e fortíssimas, e ninguém vos poderá resistir.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 10, 'Um só de vós porá em fuga mil homens dos inimigos, porque o Senhor vosso Deus combaterá por vós, como prometeu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 11, 'Sòmente tende grandíssimo cuidado em amar o Senhor vosso Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 12, 'Se quiserdes seguir os erros destes povos, que habitam entre vós, e contrair com eles matrimônios, e estabelecer amizades,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 13, 'sabei desde já que o Senhor vosso Deus não os exterminará diante de vós, mas serão para vós uma cova e um laço, um aguilhão nos vossos flancos, e espinhos nos vossos olhos, até que vos tire e vos extermine desta terra excelente que vos deu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 14, 'Eis que hoje entro no caminho de toda a terra. Reconhecei de todo o vosso coração que de todas as palavras que o Senhor prometeu cumprir em vosso favor nem uma só ficou sem efeito. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 15, 'Ora, assim como ele cumpriu de facto as suas promessas, e tudo vos tem sucedido felizmente, assim também mandará sobre vós todos os males de que vos ameaçou, até que vos tire e vos extermine desta excelente terra que vos deu,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 16, 'se violardes o pacto do Senhor vosso Deus, que ele fez convosco, se servides aos deuses estranhos e os adorardes; depressa e subitamente se levantará contra vós o furor do Senhor, e sereis tirados desta terra excelente que vos deu.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 1, 'Finalmente Josué reuniu todas as tribos de Israel em Siquém, chamou os anciães, os chefes, os juízes e os oficiais, e eles apresentaram-se diante do Senhor, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 2, 'Ele falou assim ao povo: Isto diz o Senhor Deus de Israel: Vossos pais, Taré, pai de Abraão e pai de Nacor, habitaram desde o princípio na banda de além do rio, e serviram a deuses estranhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 3, 'Eu tirei pois vosso pai Abraão dos confins da Mesopotâmia, conduzi-o à terra de Canaan e multipliquei a sua descendência,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 4, 'dando-lhe Isaac. A este dei Jacob e Esaú. A Esaú dei em possessão o monte de Seir; Jacob, porém, e seus filhos desceram ao Egipto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 5, 'Depois mandei Moisés e Aarão, e feri o Egipto com muitos milagres e prodígios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 6, 'Fiz sair vossos pais do Egipto, e chegastes ao mar. Os Egípcios perseguiram os vossos pais com carros e cavalaria até ao mar Vermelho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 7, 'Os filhos de Israel porém clamaram ao Senhor, o qual pôs trevas entre vós e os Egípcios, e fez vir o mar sobre eles, que os cobriu. Os vossos olhos viram todas as coisas que eu fiz no Egipto, e vós habitastes no deserto durante muito tempo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 8, 'Introduzi-vos na terra do Amorreu, que habitava na banda de além do Jordão. Quando combatiam contra vós, eu os entregava nas vossas mãos, vós tomastes posse do seu país, e eu os destruí diante de vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 9, 'Levantou-se Balac, filho de Sefor, rei de Moab, e combateu contra Israel. Mandou chamar Balaão, filho de Beor, para que vos amaldiçoasse,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 10, 'mas eu não o quis ouvir, antes pelo contrário por meio dele vos abençoei, e vos livrei da sua mão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 11, 'Passastes o Jordão e chegastes a Jericó. Combateram contra vós os homens desta cidade, o Amorreu, o Ferezeu, o Cananeu, o Heteu, o Gergeseu, o Heveu e o Jebuseu, e eu os entreguei nas vossas mãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 12, 'Mandei adiante de vós vespas, que os expulsaram das suas terras (assim como) os dois reis dos Amorreus. Não foi a tua espada, (não foi) o teu arco (que te deu tal vitória).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 13, 'Dei-vos uma terra que não lavrastes, cidades que não edificastes, para habitardes nelas, vinhas e olivais, que não plantastes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 14, 'Agora pois temei ao Senhor e servi-o com um coração perfeito e sinceríssimo; tirai (do meio de vós) os deuses, a que vossos pais serviram na Mesopotâmia e no Egipto, e servi ao Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 15, 'Porém, se vos parece mal servir ao Senhor, é-vos permitida a opção; escolhei hoje o que vos agrada, e a quem principalmente deveis servir: se aos deuses, a quem serviram os vossos pais na Mesopotâmia, se aos deuses dos Amorreus, em cuja terra habitais, que eu e minha casa havemos de servir ao Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 16, 'O povo, respondendo, disse: Longe de nós que abandonemos o Senhor, e sirvamos a deuses estranhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 17, 'O Senhor nosso Deus, ele mesmo, nos tirou a nós e a nossos pais da terra do Egipto, da casa da escravidão, fez à nossa vista grandes prodígios e guardou-nos por entre todos os povos; pelos quais passamos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 18, 'Expulsou todas as nações, o Amorreu, habitantente da terra em que entramos. Nós pois serviremos ao Senhor, porque ele é o nosso Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 20, 'Se abandonardes o Senhor e servirdes a deuses estranhos, ele se voltará contra vós e vos destruirá, depois de vos ter feito bem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 21, 'O povo disse a Josué: Não será assim como dizes, mas serviremos ao Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 22, 'Josué disse ao povo: Sois testemunhas de que vós mesmos escolhestes para vós o Senhor, a fim de o servir. Eles responderam: Somos testemunhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 23, 'Tirai, pois, (disse Josué) do meio de vós os deuses estranhos, e inclinai os vossos corações para o Senhor Deus de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 24, 'O povo disse a Josué: Nós serviremos ao Senhor nosso Deus, e seremos obedientes aos seus preceitos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 25, 'Josué renovou naquele dia a aliança, e deu ao povo preceitos e leis em Siquem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 26, 'Escreveu também todas estas palavras no livro da lei do Senhor, tomou uma pedra muito grande, colocou-a debaixo dum carvalho, que estava no santuário do Senhor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 27, 'e disse a todo o povo: Esta pedra servir-vos-à de testemunho de que ouviu todas as palavras, que o Senhor vos disse, para que não aconteça que depois queirais renegar o Senhor vosso Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 28, 'E despediu o povo, cada um para a sua possessão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 29, 'Depois disto morreu Josué, filho de Nun, servo do Senhor, com cento e dez anos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 30, 'Sepultaram-no nos confins da sua possessão, em Tamnat Saraa, que está situada sobre o monte de Efraim, para a parte setentrional do monte Gaas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 31, 'Israel serviu ao Senhor, durante todo o tempo da vida de Josué e dos anciães, que viveram muito tempo depois de Josué, e que sabiam todas as obras que o Senhor tinha feito em (favor de) Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 32, 'Os ossos de José, que os filhos de Israel tinham trazido do Egipto, foram sepultados em Siquem, na parte do campo, que Jacob tinha comprado aos filhos de Hemor, pai de Siquem, por cem cordeiros, e que foi depois propriedade dos filhos de José.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 33, 'Morreu também Eleázaro, filho de Aarão, e sepultaram-no em Gabaat, (cidade) de Finéas, seu filho , que lhe tinha sido dada sobre o monte de Efraim.');
